<?php

declare(strict_types=1);

require __DIR__ . '/store/layout.php';

$customer = store_require_customer($pdo);
$itemsQuery = $pdo->prepare('SELECT i.*, p.name, p.category, p.sale_price, p.list_price, p.stock, COALESCE(pi.image_url, p.image_url) AS image_url FROM pelish_customer_cart_items i INNER JOIN pelish_customer_carts c ON c.id=i.cart_id INNER JOIN pelish_products p ON p.id=i.product_id LEFT JOIN pelish_product_images pi ON pi.id=i.product_image_id WHERE c.customer_id=? ORDER BY i.created_at DESC');
$itemsQuery->execute([$customer['id']]);
$items = $itemsQuery->fetchAll();
$items = array_map(static function (array $item): array { $item['price'] = store_product_price($item); return $item; }, $items);
$subtotal = array_reduce($items, static fn(float $sum, array $item): float => $sum + ($item['price']['current'] * (int) $item['quantity']), 0.0);
$cargo = $subtotal > 0 && $subtotal < 3500 ? 79.0 : 0.0;
store_render_head('Sepetim');
store_render_header($pdo);
?>
<main class="store-main"><section class="page-intro compact"><p class="eyebrow">SEPETİM</p><h1>Seçtiklerin.</h1></section><?php if (!$items): ?><section class="commerce-empty full-empty"><p class="eyebrow">PELISH</p><h1>Sepetin henüz boş.</h1><p>İyi hissettiren bir parçayı seçtiğinde burada seni bekliyor olacak.</p><a class="button button-dark" href="indirimler.php">İndirimleri keşfet <span>→</span></a></section><?php else: ?><section class="saved-layout"><div class="saved-products"><?php foreach ($items as $item): ?><article class="saved-card"><a href="urun.php?id=<?= (int) $item['product_id'] ?>"><img src="<?= e($item['image_url'] ?: 'https://images.unsplash.com/photo-1485968579580-b6d095142e6e?auto=format&fit=crop&w=900&q=85') ?>" alt="<?= e($item['name']) ?>"></a><div class="saved-card-copy"><small><?= e($item['category']) ?></small><h2><?= e($item['name']) ?></h2><strong class="cart-item-price"><?php if ($item['price']['is_discounted']): ?><del><?= store_money($item['price']['original']) ?></del><?php endif; ?><?= store_money($item['price']['current']) ?></strong><div class="cart-variants"><small class="cart-size">Beden: <?= e($item['selected_size']) ?></small><?php if ($item['color_name']): ?><small class="cart-color"><i style="--cart-color:<?= e($item['color_hex'] ?: '#bbb') ?>"></i>Renk: <?= e($item['color_name']) ?></small><?php endif; ?></div><div class="saved-card-actions cart-line-actions"><form method="post" action="store/action.php"><input type="hidden" name="csrf" value="<?= e(store_csrf()) ?>"><input type="hidden" name="action" value="cart-quantity"><input type="hidden" name="line_id" value="<?= (int) $item['id'] ?>"><input type="hidden" name="change" value="-1"><input type="hidden" name="return_to" value="sepetim.php"><button type="submit" <?= (int) $item['quantity'] === 1 ? 'disabled' : '' ?> aria-label="Adedi azalt">−</button></form><output><?= (int) $item['quantity'] ?> adet</output><form method="post" action="store/action.php"><input type="hidden" name="csrf" value="<?= e(store_csrf()) ?>"><input type="hidden" name="action" value="cart-quantity"><input type="hidden" name="line_id" value="<?= (int) $item['id'] ?>"><input type="hidden" name="change" value="1"><input type="hidden" name="return_to" value="sepetim.php"><button type="submit" aria-label="Adedi artır">+</button></form><form method="post" action="store/action.php"><input type="hidden" name="csrf" value="<?= e(store_csrf()) ?>"><input type="hidden" name="action" value="cart-remove"><input type="hidden" name="line_id" value="<?= (int) $item['id'] ?>"><input type="hidden" name="return_to" value="sepetim.php"><button class="remove-line" type="submit">Kaldır</button></form></div></div></article><?php endforeach; ?></div><aside class="cart-summary"><h2>Sipariş özeti</h2><p><span>Ürünler (<?= array_sum(array_column($items, 'quantity')) ?>)</span><strong><?= store_money($subtotal) ?></strong></p><p><span>Kargo</span><strong><?= $cargo ? store_money($cargo) : 'Ücretsiz' ?></strong></p><p class="cart-total"><span>Toplam</span><strong><?= store_money($subtotal + $cargo) ?></strong></p><button class="button button-dark" type="button" data-store-toast="Ödeme adımı çok yakında aktif olacak.">Ödemeye geç <span>→</span></button><small>Ürünlerin hesabında güvenle saklanır.</small></aside></section><?php endif; ?></main>
<?php store_render_footer(); ?>
